package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.AnnotatedParameter;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for POJOPropertyBuilder#removeNonVisible
 */
public class POJOPropertyBuilder_removeNonVisible_TriageGen0Test {

    private MapperConfig<?> mockConfig;
    private AnnotationIntrospector mockAi;
    private PropertyName mockName;

    @Before
    public void setUp() {
        mockConfig = mock(MapperConfig.class);
        mockAi = mock(AnnotationIntrospector.class);
        mockName = PropertyName.construct("testProperty");
    }

    /**
     * Helper to create a builder with specific state.
     * Since findAccess() is protected/internal, we rely on the fact that 
     * the builder state is manipulated via add methods.
     */
    private POJOPropertyBuilder createBuilder(boolean forSerialization) {
        return new POJOPropertyBuilder(mockConfig, mockAi, forSerialization, mockName);
    }

    @Test
    public void testRemoveNonVisible_AccessAuto_InferMutatorsTrue() {
        // Case: AUTO, inferMutators = true
        // Behavior: _getters and _ctorParameters are filtered. 
        // _fields and _setters are only filtered if (inferMutators is false OR getters become null)
        POJOPropertyBuilder builder = createBuilder(true);

        // Mocking behavior of _removeNonVisible is impossible as it's private, 
        // but we can verify the logic flow by adding members.
        // Note: In a real Jackson environment, _removeNonVisible relies on visibility.
        // Here we simulate the outcome.

        // Since we cannot easily mock the internal _removeNonVisible call without PowerMock,
        // we test the logic paths provided by the switch/if structure.

        builder.removeNonVisible(true);
        // If AUTO and inferMutators is true, and we assume _removeNonVisible keeps them:
        // No assertion on content because we can't control the visibility logic without a real Introspector,
        // but this covers the branch for default/AUTO.
    }

    @Test
    public void testRemoveNonVisible_AccessAuto_InferMutatorsFalse() {
        // Case: AUTO, inferMutators = false
        // Behavior: _fields and _setters MUST be processed by _removeNonVisible
        POJOPropertyBuilder builder = createBuilder(true);
        builder.removeNonVisible(false);
    }

    @Test
    public void testRemoveNonVisible_AccessReadOnly_ForSerializationTrue() {
        // Case: READ_ONLY, _forSerialization = true
        // Behavior: _setters = null, _ctorParameters = null, _fields is NOT null (because !forSerialization is false)

        // To trigger READ_ONLY, we need a way to set the access. 
        // In Jackson, this is usually done via @JsonProperty(access = READ_ONLY)
        // Since we are unit testing the method logic, we assume a subclass or 
        // a mock that returns READ_ONLY for findAccess().

        POJOPropertyBuilder builder = spy(createBuilder(true));
        doReturn(JsonProperty.Access.READ_ONLY).when(builder).findAccess();

        // Add some members to see if they get cleared
        AnnotatedMethod setter = mock(AnnotatedMethod.class);
        builder.addSetter(setter, mockName, false, true, false);

        builder.removeNonVisible(true);

        assertFalse("Setters should be null", builder.hasSetter());
        assertTrue("Fields should remain because forSerialization is true", builder.hasField());
    }

    @Test
    public void testRemoveNonVisible_AccessReadOnly_ForSerializationFalse() {
        // Case: READ_ONLY, _forSerialization = false
        // Behavior: _setters = null, _ctorParameters = null, _fields = null

        POJOPropertyBuilder builder = spy(createBuilder(false));
        doReturn(JsonProperty.Access.READ_ONLY).when(builder).findAccess();

        AnnotatedField field = mock(AnnotatedField.class);
        builder.addField(field, mockName, false, true, false);
        builder.addSetter(mock(AnnotatedMethod.class), mockName, false, true, false);

        builder.removeNonVisible(true);

        assertFalse("Fields should be null", builder.hasField());
        assertFalse("Setters should be null", builder.hasSetter());
    }

    @Test
    public void testRemoveNonVisible_AccessReadWrite() {
        // Case: READ_WRITE
        // Behavior: No trimming whatsoever
        POJOPropertyBuilder builder = spy(createBuilder(true));
        doReturn(JsonProperty.Access.READ_WRITE).when(builder).findAccess();

        AnnotatedField field = mock(AnnotatedField.class);
        builder.addField(field, mockName, false, true, false);

        builder.removeNonVisible(true);
        assertTrue("Fields should still exist in READ_WRITE", builder.hasField());
    }

    @Test
    public void testRemoveNonVisible_AccessWriteOnly_ForSerializationTrue() {
        // Case: WRITE_ONLY, _forSerialization = true
        // Behavior: _getters = null, _fields = null
        POJOPropertyBuilder builder = spy(createBuilder(true));
        doReturn(JsonProperty.Access.WRITE_ONLY).when(builder).findAccess();

        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        builder.addGetter(getter, mockName, false, true, false);
        AnnotatedField field = mock(AnnotatedField.class);
        builder.addField(field, mockName, false, true, false);

        builder.removeNonVisible(true);

        assertFalse("Getters should be null", builder.hasGetter());
        assertFalse("Fields should be null", builder.hasField());
    }

    @Test
    public void testRemoveNonVisible_AccessWriteOnly_ForSerializationFalse() {
        // Case: WRITE_ONLY, _forSerialization = false
        // Behavior: _getters = null, _fields is NOT null
        POJOPropertyBuilder builder = spy(createBuilder(false));
        doReturn(JsonProperty.Access.WRITE_ONLY).when(builder).findAccess();

        AnnotatedMethod getter = mock(AnnotatedMethod.class);
        builder.addGetter(getter, mockName, false, true, false);
        AnnotatedField field = mock(AnnotatedField.class);
        builder.addField(field, mockName, false, true, false);

        builder.removeNonVisible(true);

        assertFalse("Getters should be null", builder.hasGetter());
        assertTrue("Fields should remain because forSerialization is false", builder.hasField());
    }

    @Test
    public void testRemoveNonVisible_AccessNull_DefaultsToAuto() {
        // Case: findAccess() returns null -> defaults to AUTO
        POJOPropertyBuilder builder = spy(createBuilder(true));
        doReturn(null).when(builder).findAccess();

        // This tests the 'if (acc == null)' branch and the 'default' case
        builder.removeNonVisible(true);
        // Verification: if it didn't crash, the logic flow reached default/AUTO
    }
}
